steps.script:
# Lowest effective z of any ghost MUST beat the highest effective z of every
# movement board overlay. Effective z = sum of z_index up the parent chain while
# z_as_relative holds — that is the key the renderer sorts on.
var m = tree.root.get_node("Main")
var eff := func(ci: CanvasItem) -> int:
	var z := 0
	var cur: Node = ci
	while cur is CanvasItem:
		z += (cur as CanvasItem).z_index
		if not (cur as CanvasItem).z_as_relative:
			break
		cur = cur.get_parent()
	return z
var lowest_ghost := 1 << 30
for c in m.get_node("BoardRoot/MovementGhostVisual").get_children():
	if c is CanvasItem:
		lowest_ghost = min(lowest_ghost, eff.call(c))
var highest_overlay := -(1 << 30)
for path in ["BoardRoot/MoveRangeVisual", "BoardRoot/MovementERVisual", "BoardRoot/MovementCoherencyVisual"]:
	var layer = m.get_node_or_null(path)
	if layer == null:
		continue
	highest_overlay = max(highest_overlay, eff.call(layer))
	for c in layer.get_children():
		if c is CanvasItem:
			highest_overlay = max(highest_overlay, eff.call(c))
m.set_meta("z_probe", "ghost_min=%d overlay_max=%d" % [lowest_ghost, highest_overlay])
return lowest_ghost > highest_overlay

# The distance-moved readout rides with the ghosts, so it clears the overlays
# too. Compared against the same effective-z the renderer sorts on, not an
# absolute number (BoardRoot itself carries a large negative z offset).
var m = tree.root.get_node("Main")
var eff := func(ci: CanvasItem) -> int:
	var z := 0
	var cur: Node = ci
	while cur is CanvasItem:
		z += (cur as CanvasItem).z_index
		if not (cur as CanvasItem).z_as_relative:
			break
		cur = cur.get_parent()
	return z
var lbl = m.get_node_or_null("BoardRoot/MovementGhostVisual/MovementRemainingLabel")
if lbl == null or lbl.text == "":
	return false
var highest_overlay := -(1 << 30)
for path in ["BoardRoot/MoveRangeVisual", "BoardRoot/MovementERVisual", "BoardRoot/MovementCoherencyVisual"]:
	var layer = m.get_node_or_null(path)
	if layer == null:
		continue
	for c in layer.get_children():
		if c is CanvasItem:
			highest_overlay = max(highest_overlay, eff.call(c))
m.set_meta("label_probe", "%s @z=%d overlay_max=%d" % [lbl.text, eff.call(lbl), highest_overlay])
return eff.call(lbl) > highest_overlay

# Thin reach circles: with one circle per dragged model a heavy stroke floods
# the drop zone. Report the widest dash actually drawn.
var m = tree.root.get_node("Main")
var w := 0.0
for c in m.get_node("BoardRoot/MoveRangeVisual").get_children():
	if c is Line2D:
		w = max(w, (c as Line2D).width)
return w

# Pad carry is the case that used to be strictly worse: the reach ring is
# deliberately lifted (dash.z_index = 50) so the clamp boundary reads over the
# board tokens. It must still pass UNDER the carried ghost.
var m = tree.root.get_node("Main")
var eff := func(ci: CanvasItem) -> int:
	var z := 0
	var cur: Node = ci
	while cur is CanvasItem:
		z += (cur as CanvasItem).z_index
		if not (cur as CanvasItem).z_as_relative:
			break
		cur = cur.get_parent()
	return z
var lifted := 0
var highest_overlay := -(1 << 30)
for c in m.get_node("BoardRoot/MoveRangeVisual").get_children():
	if c is CanvasItem:
		highest_overlay = max(highest_overlay, eff.call(c))
		if (c as CanvasItem).z_index == 50:
			lifted += 1
var lowest_ghost := 1 << 30
for c in m.get_node("BoardRoot/MovementGhostVisual").get_children():
	if c is CanvasItem:
		lowest_ghost = min(lowest_ghost, eff.call(c))
m.set_meta("pad_z_probe", "lifted_dashes=%d ghost_min=%d overlay_max=%d" % [lifted, lowest_ghost, highest_overlay])
return lifted > 0 and lowest_ghost > highest_overlay
